def minBuckets(street):
    n = len(street)
    buckets = 0
    i = 0
    while i < n:
        if street[i] == 'H':
            if i + 1 < n and street[i + 1] == '.':
                buckets += 1
                i += 3
            elif i > 0 and street[i - 1] == '.':
                buckets += 1
                i += 1
            else:
                return -1
        else:
            i += 1
    return buckets
